css:
.cat-window-demo{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px 4px 14px;font-family:var(--cat-font-family-ui)}
.cat-win-tabs{display:flex;align-items:center;gap:5px}
.cat-wtab{display:inline-flex;align-items:center;height:30px;padding:0 12px;border-radius:7px;border:1px solid transparent;background:transparent;font:500 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-mid);cursor:pointer;transition:all var(--cat-motion-fast) ease}
.cat-wtab:hover{background:rgba(255,255,255,.35);color:var(--cat-color-ink-hi)}
.cat-wtab.is-active{background:var(--cat-semantic-tab-a);border-color:rgba(255,255,255,.85);color:var(--cat-color-ink-hi);font-weight:var(--cat-font-weight-semibold);box-shadow:0 1px 2px rgba(25,35,65,.08)}
.cat-wtab.add{width:26px;height:26px;padding:0;border-radius:50%;justify-content:center}
.cat-win-controls{display:flex;gap:2px}
.cat-win-btn{display:grid;place-items:center;width:30px;height:26px;border-radius:var(--cat-size-radius-sm);background:none;border:none;color:var(--cat-color-ink-hi);font-size:11px;cursor:pointer;transition:background var(--cat-motion-fast),transform var(--cat-motion-fast)}
.cat-win-btn:hover{background:rgba(0,0,0,.06)}
.cat-win-btn:active{transform:scale(.92)}
.cat-win-btn.close:hover{background:var(--cat-color-danger-base);color:#fff}
.cat-win-btn.close:active{background:var(--cat-color-danger-hover)}
.cat-window{display:flex;flex-direction:column;border-radius:var(--cat-size-radius-window);background:var(--cat-semantic-glass-window,var(--cat-color-surface-glass-window));backdrop-filter:blur(var(--cat-blur-window)) saturate(var(--cat-blur-saturate-window));-webkit-backdrop-filter:blur(var(--cat-blur-window)) saturate(var(--cat-blur-saturate-window));border:1px solid var(--cat-color-stroke-light);box-shadow:var(--cat-elevation-window),inset 0 1px 0 rgba(255,255,255,.65)}
